/* 引用文本 (q 标签) */
.mes_text q,
.mes_text blockquote {
    /* 关键：让换行后的每行都独立应用样式 */
    -webkit-box-decoration-break: clone !important;
    box-decoration-break: clone !important;

    /* 樱粉渐变：透明 → 樱粉 → 透明 */
    background: linear-gradient(to right, 
        rgba(255, 188, 193, 0),    /* 左边完全透明 */
        rgba(229, 205, 218, 0.2),  /* 中间樱粉 */
        rgba(255, 188, 193, 0)      /* 右边完全透明 */
    ) !important;

    /* 文字颜色 */
    color: rgba(190, 172, 176, 1) !important;

    /* 【关键修改】上下padding设为0，左右保留极窄空间 */
    padding: 0 1px !important;      /* ✏️【内边距】上下为0，左右1px */

    /* 确保没有其他间距 */
    margin: 0 !important;
    border: none !important;

    /* 继承父元素的行高，不额外增加 */
    line-height: inherit !important;

    /* 没有任何阴影或装饰 */
    text-shadow: none !important;
    box-shadow: none !important;
}

/* 如果是块级引用，保持行内显示 */
.mes_text blockquote {
    display: inline !important;
    margin: 0 !important;
    padding: 0 1px !important;
}

/* 如果还是太宽，可能是父元素有行高，强制设一个较小的行高 */
.mes_text {
    line-height: 1.5 !important;  /* ✏️【行高】可调，越小越紧凑 */
}

/* 单独调整名字位置 - 最高层级 */
.mes .name_text {
    position: relative !important;
    top: -120px !important;
    left: 163px !important;
    font-style: italic !important;
    font-size: 15px !important;
    color: #FFFFFF !important;
    z-index: 9999 !important;
    isolation: isolate !important;
}

/* 父容器也提升层级 */
.mes .mes_block {
    position: relative !important;
    z-index: 100 !important;
}



/* ===== 预设条目 - 毛玻璃白粉美化 ===== */

/* 预设列表整体容器 - 半透明白粉毛玻璃 */
#completion_prompt_manager #completion_prompt_manager_list {
    background: rgba(255, 240, 245, 0.25) !important;  /* ✏️【背景】极透白粉 */
    backdrop-filter: blur(8px) !important;             /* ✏️【毛玻璃强度】 */
    -webkit-backdrop-filter: blur(8px) !important;
    border-radius: 12px !important;
    padding: 8px !important;
}

/* 单个预设条目容器 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt {
    background: rgba(255, 245, 250, 0.3) !important;   /* ✏️【条目背景】更透的白粉 */
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    border-radius: 8px !important;
    margin: 4px 0 !important;
    padding: 6px 10px !important;
    border: 1px solid rgba(255, 200, 220, 0.3) !important; /* 极淡粉边 */

    /* 去掉任何灰色背景 */
    background-image: none !important;
    box-shadow: none !important;
}

/* 预设条目名称 - 启用状态 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .completion_prompt_manager_prompt_name {
    color: #8B5A6B !important;  /* ✏️【文字色】深粉 */
    font-weight: 500 !important;
}

/* 预设条目名称 - 禁用状态（用你给的粉色半透明） */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: rgb(190 118 135 / 0.56) !important;  /* 保留你给的粉色 */
    font-style: italic !important;
    opacity: 0.8 !important;
}

/* 预设条目图标 - 启用状态 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: #FFB6C1 !important;  /* ✏️【图标色】浅粉 */
}

/* 预设条目图标 - 禁用状态 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .fa-solid {
    color: rgb(190 118 135 / 0.4) !important;
}

/* 悬停效果 - 轻微加深 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:hover {
    background: rgba(255, 235, 245, 0.4) !important;
    border-color: rgba(255, 180, 200, 0.5) !important;
    transition: all 0.2s ease !important;
}

/* 去掉任何默认的灰色背景 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt * {
    background-image: none !important;
}

