/* ===== 角色卡头像框线 - 粉白（去多余圈版） ===== */

/* 头像容器本身 */
.character_select .avatar,
#rm_print_characters_block .avatar,
#rm_ch_create_block .avatar,
#avatar_div .avatar,
#user_avatar_block .avatar,
.persona_management_left_column .avatar,
.hotswap .avatar,
.inline_avatar {
    position: relative !important;
    border: 2px solid #FFD9E2 !important;        /* 只保留外边框 */
    border-radius: 50% !important;
    box-shadow: none !important;                  /* 去掉所有阴影 */
    outline: none !important;
    background: transparent !important;           /* 背景透明 */
    overflow: hidden !important;                  /* 隐藏溢出 */
}

/* 头像图片本身 */
.character_select .avatar img,
#rm_print_characters_block .avatar img,
#rm_ch_create_block .avatar img,
#avatar_div .avatar img,
#user_avatar_block .avatar img,
.persona_management_left_column .avatar img,
.hotswap .avatar img,
.inline_avatar img {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
}

/* 清除所有可能的伪元素圈圈 */
.character_select .avatar::before,
.character_select .avatar::after,
#rm_print_characters_block .avatar::before,
#rm_print_characters_block .avatar::after,
#rm_ch_create_block .avatar::before,
#rm_ch_create_block .avatar::after,
#avatar_div .avatar::before,
#avatar_div .avatar::after,
#user_avatar_block .avatar::before,
#user_avatar_block .avatar::after,
.persona_management_left_column .avatar::before,
.persona_management_left_column .avatar::after,
.hotswap .avatar::before,
.hotswap .avatar::after,
.inline_avatar::before,
.inline_avatar::after {
    display: none !important;
    content: none !important;
    opacity: 0 !important;
    visibility: hidden !important;
}

/* 去掉任何可能残留的圈圈背景 */
.avatar {
    background: transparent !important;
    background-image: none !important;
}

/* 确保没有其他元素造成圈圈 */
.avatar > *:not(img) {
    display: none !important;
}
